head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vMktactCd = '303'; // 채권시장조치구분코드
scwin.vBndListProcsTpCd = 1; // 채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.vViewYN = 'N';
scwin.vRowPos = 0;
scwin.received_std_cd = ""; // 타화면에서 이 화면 오픈 시 건넨 표준코드
scwin.received_procs_tp = "";
scwin.vIsuCd = '', scwin.hasAttachDoc = '';
scwin.gBndApplId, scwin.gProcsStat = '';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; // 접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9
scwin.btnStat = new Object();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.bns.BnsPanelToGroupBox(pnl_Req); // 패널라운드처리(신청)
        $c.bns.BnsPanelToGroupBox(pnl_DtlInfo); // 패널라운드처리(상세)
        $c.bns.BnsPanelToGroupBox(pnl_Acpt); // 패널라운드처리(접수)

        btn_Excel.hide();

        // 타화면에서 이 화면 오픈 시 건넨 값 저장
        scwin.received_std_cd = $c.stf.getQuery(frame.srcUrl, "STD_CD");
        scwin.received_procs_tp = $c.stf.getQuery(frame.srcUrl, "PROCS_TP"); // (A:미신고,B:대용납입확인필요,C:신고완료,D:접수완료,E:처리완료)

        // 접수완료, 처리완료 인 경우 tab2로 이동.
        if (scwin.received_procs_tp === "D" || scwin.received_procs_tp === "E") {
            tab_List.setSelectedTabIndex(2);
        } else {
            tab_List.setSelectedTabIndex(1);
        }
        scwin.vBndListProcsTpCd = tab_List.getSelectedTabIndex();
        scwin.listSync(); // 목록 조회

        // 팀장확인데이터셋설정

        // dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_Temp.insertRow();
        // 필드 ReadOnly 속성 제거/부여
        scwin.chgTabAct(scwin.vBndListProcsTpCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_List_OnSelChanged
 * @description tab List On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_List_OnSelChanged = function(nIndex) {
    try {
        scwin.vBndListProcsTpCd = nIndex;
        if (scwin.vBndListProcsTpCd === 2) {
            txb_Dtl.setValue("중도상환(부분) 접수내역");
            btn_Excel.show("");
        } else {
            txb_Dtl.setValue("중도상환(부분) 신청내역");
            btn_Excel.hide();
        }
        scwin.listSync(); // 목록 조회
        // 필드 ReadOnly 속성 제거/부여
        scwin.chgTabAct(scwin.vBndListProcsTpCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.tab_List_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10500.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        // 타화면에서 건네받은 표준코드가 존재하면 그 건을 선택
        if (scwin.received_std_cd !== "") {
            for (let i = 1; i <= dts_List.getRowCount(); i++) {
                if (scwin.received_std_cd === dts_List.getCellData(i, "STD_CD")) {
                    dts_List.setRowPosition(i, 0);
                    scwin.received_std_cd = ""; // 한번쓰고 초기화한다.
                    scwin.received_procs_tp = "";
                }
            }
        }
        if (scwin.vBndListProcsTpCd === 2) {
            // 접수,수정,처리완료,팀장확인 시 해당 ROW로 이동
            $c.bns.fn_RowPos(dts_List, scwin.vRowPos);
        } else {
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        if (row > 0) {
            scwin.gBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
            scwin.dtlSync();
            scwin.gProcsStat = dts_List.getCellData(row, "PROCS_STAT");
            scwin.procBtnStat();

            // 채권신고담당자 조회
            scwin.search2();
        } else {
            dts_DtlInfo.removeAll();
            dts_List3.removeAll();
            scwin.vDtlInfoRowCount = 0;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.dts_List_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadError
 * @description dts_DtlInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10500.dts_DtlInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadCompleted
 * @description dts_DtlInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vDtlInfoRowCount = rowcount;
        edt_ListAmt.RightMargin = 5;
        edt_RedmptAmt.RightMargin = 5;
        edt_BfchgStripNsprtBal.RightMargin = 5;
        edt_AfchgListAmt.RightMargin = 5;
        edt_AfchgStripNsprtBal.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.dts_DtlInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List2_onheadcheckclick
 * @description grd_List2 onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_List2_onheadcheckclick = function(col, colid, bCheck) {
    try {
        scwin.setCheckBoxALL(grd_List2, dts_List, bCheck);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.grd_List2_onheadcheckclick" });
    }
};

/**
 * @method
 * @name img_StrtDd_onclick
 * @description img_StrtDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_StrtDd_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        popUpCalendar2(edt_StrtDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.img_StrtDd_onclick" });
    }
};

/**
 * @method
 * @name img_DelDd_onclick
 * @description img_DelDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_DelDd_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        popUpCalendar2(edt_RsnOccrDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.img_DelDd_onclick" });
    }
};

/**
 * @method
 * @name btn_Acpt_onclick
 * @description 「접수」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Acpt_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.processGp = '1';
        await scwin.acpt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10500.btn_Acpt_onclick" });
    }
};

/**
 * @method
 * @name btn_Ret_onclick
 * @description 「반송」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Ret_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.processGp = '2';
        scwin.fn_GetPar = scwin.getReturn;
        scwin.fn_SetPar = scwin.setReturn;
        $c.bns.fn_PopReturn(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.btn_Ret_onclick" });
    }
};

/**
 * @method
 * @name btn_Ret2_onclick
 * @description 「반송」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Ret2_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        // 접수 후 수정 및 반송시 체크한다.
        if ($c.bns.fn_CheckModAndRet('ULDBNS10500.xml', dts_CheckCmData, scwin.gBndApplId) > 0) return;
        scwin.processGp = '2';
        scwin.fn_GetPar = scwin.getReturn;
        scwin.fn_SetPar = scwin.setReturn;
        $c.bns.fn_PopReturn(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.btn_Ret2_onclick" });
    }
};

/**
 * @method
 * @name btn_Attach_onclick
 * @description 「첨부파일확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Attach_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        if ("N" === dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC")) {
            await $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
            return;
        }
        scwin.fn_GetPar = scwin.getCommonKey;
        $c.bns.fn_PopAttachDocSearch(grd_List1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10500.btn_Attach_onclick" });
    }
};

/**
 * @method
 * @name btn_Dtl_onclick
 * @description 「종목상세내역」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Dtl_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.fn_GetPar = scwin.getParIsuDelInfo;
        $c.bns.fn_PopIsuDetail(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.btn_Dtl_onclick" });
    }
};

