 */
scwin.btn_ApprovFileCreat_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.fn_GetPar = scwin.getParApprovFileWrt;
        $c.bns.fn_PopApprovFileWrt(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.btn_ApprovFileCreat_onclick" });
    }
};

/**
 * @method
 * @name btn_Proc_onclick
 * @description 「처리완료」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Proc_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        if (scwin.btnStat.Proc === "dis") return;
        scwin.vRowPos = dts_List.getRowPosition();
        scwin.processGp = '3';
        await scwin.procsComplt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10500.btn_Proc_onclick" });
    }
};

/**
 * @method
 * @name btn_Mod_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Mod_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.vRowPos = dts_List.getRowPosition();
        scwin.processGp = '4';
        await scwin.procsComplt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10500.btn_Mod_onclick" });
    }
};

/**
 * @method
 * @name btn_TeamleadrConfrm_onclick
 * @description 「팀장확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_TeamleadrConfrm_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.processGp = "6";

        // 체크된 것 카운팅
        let nTrueCnt = 0;
        for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
            if (dts_List.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
            }
        }
        if (nTrueCnt === 0) {
            await $c.win.alert("선택된 정보가 없습니다.");
            return false;
        }
        $c.bns.fn_TeamleadrConfrmAll('ULDBNS10500.xml', trs_Save, dts_List, scwin.vBndListProcsTpCd, nTrueCnt);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10500.btn_TeamleadrConfrm_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        if (scwin.processGp === '1') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "접수"));
        }
        if (scwin.processGp === '3') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
        }
        if (scwin.processGp === '4') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
        }
        if (scwin.processGp === '6') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10500.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (scwin.processGp === '1') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "접수"));
        }
        if (scwin.processGp === '3') {
            await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        }
        if (scwin.processGp === '4') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        }
        if (scwin.processGp === '6') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
        }
        scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS10500.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name edt_ListAmt_onkillfocus
 * @description edt_ListAmt onkillfocus 이벤트
