/**
 * @method
 * @name dts_DtlInfo_OnColumnChanged
 * @description Dtl Info On Column Changed 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlInfo_OnColumnChanged = function(row, colid) {
    try {
        if (colid === "REDMPT_AMT" || colid === "BFCHG_LIST_AMT") {
            /** 상환후 상장잔액(화면 자동 계산) */
            if (scwin.vBndListProcsTpCd = 2) {
                edt_AfchgListAmt.setValue(Number(edt_ListAmt.getValue()) - Number(edt_RedmptAmt.getValue()));
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS10500.dts_DtlInfo_OnColumnChanged" });
    }
};

