    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        /**********************************************
         * Event   : btn_Excel > onclick
         * 설명    : 엑셀버튼클릭
         ***********************************************/
        // 엑셀 로그
        $c.stf.doLogSave('ULDBNS10500.xml', SCREN_PROCS_TP_CD_07);
