/**
 * @method
 * @name stripAmtCheck
 * @description 2006년 이전이거나 발행된 만기 3년이상 국고채권이 아닌경우 미분류 잔액이 존재안함 (5년물에서 3년물로 수정 jackal_150127)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.stripAmtCheck = async function() {
    const vIsurCd = dts_DtlInfo.getCellData(dts_DtlInfo.getRowPosition(), "ISUR_NM");
    if (vIsurCd.substring(0, 5) === "GB035") {
        const vIsuDd = dts_DtlInfo.getCellData(dts_DtlInfo.getRowPosition(), "ISU_DD");
        const vRedmptDd = dts_DtlInfo.getCellData(dts_DtlInfo.getRowPosition(), "REDMPT_DD");
        const vExprTerm = (vRedmptDd - vIsuDd) / 10000;
        if ((vIsuDd < 20060101) || (vExprTerm < 3)) {
            const vStripBal = edt_AfchgStripNsprtBal.getValue();
            if (!((vStripBal === null) || (vStripBal === "") || (vStripBal === "0"))) {
                await $c.win.alert("스트립미분리잔액은 2006년 이후 발행된 만기 3년이상 국고채권만 해당됩니다.\n시스템 담당자에게 해당종목을 문의하십시요.");
                return false;
            }
        }
    }
    return true;
};

/**
 * @method
 * @name inputCheck
 * @description 필수 입력 값을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function() {
    if (edt_StrtDd.getValue() === '') {
        await $c.win.alert("[적용일]을 입력하십시오.");
        edt_StrtDd.focus();
        return false;
    }
    if ($c.bns.fn_CheckDateObj(edt_StrtDd, "적용일")) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name acptProcsCheck
 * @description 접수, 처리완료시 공통 체크 구문
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.acptProcsCheck = async function() {
    // 스트립미분리잔액 체크
    if (await scwin.stripAmtCheck() === false) return 1;

    // 필수입력값 체크
    if (await scwin.inputCheck() === false) return 1;

    // 적용일이 등록말소일과 같거나 앞일 경우 메세지를 띄우면서 입력 제한
    if (edt_StrtDd.getValue() <= edt_RsnOccrDd.getValue()) {
        await $c.win.alert("적용일이 등록말소일 이전입니다. 다시 입력하십시오.");
        edt_StrtDd.focus();
        return 1;
    }

    // 적용일,매매일,마감일,채권마감 체크
    if ($c.bns.fn_CheckCmData('ULDBNS10500.xml', dts_CheckCmData, edt_StrtDd.getValue(), scwin.gBndApplId) > 0) return 1;
    scwin.vIsuCd = dts_DtlInfo.getCellData(1, "ISU_CD");
    scwin.hasAttachDoc = dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC");

    // 변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    return 0;
};

/**
 * @method
 * @name acpt
 * @description 신청데이터를 접수 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.acpt = async function() {
    // 접수, 처리완료 공통 체크
    if (await scwin.acptProcsCheck() > 0) return;

    // 복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRule('ULDBNS10500.xml', dts_Temp, scwin.vIsuCd, scwin.vMktactCd, edt_StrtDd.getValue()) > 0) return;

    // 첨부문서 체크
    if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '접수')) return;
    let url = "/bns/IsuChgAmt.do?method=processApplAcpt";
    url += "&SCREN_ID=" + 'ULDBNS10500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};

/**
 * @method
 * @name procsComplt
 * @description 처리완료 및 수정을 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procsComplt = async function() {
    // 접수, 처리완료 공통 체크
    if (await scwin.acptProcsCheck() > 0) return;

    // 복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRuleProcEnd('ULDBNS10500.xml', dts_Temp, scwin.vIsuCd, scwin.vMktactCd, edt_StrtDd.getValue()) > 0) return;
    let url;
    if (scwin.processGp === '4') {
        // 접수 후 수정 및 반송시 체크한다.
        if ($c.bns.fn_CheckModAndRet('ULDBNS10500.xml', dts_CheckCmData, scwin.gBndApplId) > 0) return;
        if (!confirm("수정처리 하시겠습니까?")) return;
        url = "/bns/IsuChgAmt.do?method=updateAcpt";
    } else {
        if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '처리완료')) return;
        url = "/bns/IsuChgAmt.do?method=processAcptProcessComplt";
    }
    url += "&SCREN_ID=" + 'ULDBNS10500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};

