/**
 * @method
 * @name chgTabAct
 * @description 필드 ReadOnly 속성 제거/부여
 * @param {String} vBndListProcsTpCd vBndListProcsTpCd
 * @returns {void}
 * @hidden N
 */
scwin.chgTabAct = function(vBndListProcsTpCd) {
    // 중도상환금액, 상환이전상장금액(상장잔액), 변경전스트립미분리잔액
    if (scwin.vBndListProcsTpCd === 1) {
        edt_RedmptAmt.setReadOnly("true");
        edt_RsnOccrDd.setReadOnly("true");
        // 달력가리기
        img_DelDd.hide();
    } else if (scwin.vBndListProcsTpCd === 2) {
        edt_RedmptAmt.setReadOnly("false");
        edt_RsnOccrDd.setReadOnly("false");
        // 달력보이기
        img_DelDd.show("");
    }
};

/**
 * @method
 * @name setCheckBoxALL
 * @description 그리드 체크박스 전체선택 또는 전체선택 해제
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.setCheckBoxALL = function(grdObj, dtsObj, bCheck) {
    let vcd = "";
    if (bCheck === '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        // if (dtsObj.NameString(i, "PROCS_STAT") != '처리완료') { //처리완료만 팀장확인 대상임
        if (dtsObj.getCellData(i, "PROCS_STAT") !== '처리완료' || (dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") !== "undefined" && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") !== '-' && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") !== '')) {
            // 처리완료만 팀장확인 대상임
            dtsObj.setCellData(i, "CHK", "F");
        } else {
            dtsObj.setCellData(i, "CHK", vcd);
        }
    }
    grdObj.setBroadcast(true);
};

/**
 * @method
 * @name setTransData
